"""A boss-goal Y jump converges on the aim it started with, not a moving cell.

Issue #4796 (g1288-b1680690, 第9話): the pursuit Y view calls
``_apply_skull_boss`` on every frame, so ``boss_probe_cell`` keeps answering
the boss's newest cell while the jump walks. The residual stayed at 5-7 view
px for months — every jump hit the move limit, aborted, and the redirect
order was never issued (10+ in-game months with zero boss battles). The jump
now freezes the first computed goal cell for its lifetime; the pursuit
re-aims on the next cycle.
"""
from docich.hanjuku_speedrun.hanjuku.os_layer import navigation as nav


class _Frame:
    def digest(self):
        return 'f1'

    def png_bytes(self):
        return b''


def _mem():
    return {'chapter': 9, 'tick': 100, '_records': [],
            'y_jump': {'goal': 'ボス', 'mode': 'target', 'step': 'PURSUIT',
                       'moves': 0, 'wait': 0, 'tick': 100}}


def _patch_cursor(monkeypatch, cursor, cells):
    cells_iter = iter(cells)
    monkeypatch.setattr(nav, 'world_cursor', lambda f, ch: cursor)
    monkeypatch.setattr(nav, 'world_flags', lambda f, ch, c: {})
    monkeypatch.setattr(nav, 'boss_probe_cell',
                        lambda m, g, s: next(cells_iter, cells[-1]))


def test_a_boss_jump_freezes_the_first_aim_cell(monkeypatch):
    # The view cursor sits on the frozen aim's pixel; the live cell has
    # moved 400 world px away. Without the freeze the residual would be
    # ~50 view px and the confirm path would be unreachable.
    mem = _mem()
    ox, oy = nav.Y_JUMP_OFFSET[9]
    _patch_cursor(monkeypatch, (900 / 8 + ox, 500 / 8 + oy), [(900, 500), (500, 200)])
    actions = nav._y_jump_step(mem, _Frame())
    assert actions and actions[0]['buttons'] == ['a']
    assert 'y_jump' not in mem
    confirms = [r for r in mem['_records'] if r['decision'] == 'y_jump_confirm']
    assert confirms and confirms[0]['observed_metric']['residual'] == [0.0, 0.0]


def test_the_frozen_cell_is_recorded_for_the_landing(monkeypatch):
    mem = _mem()
    # Cursor far from the aim: the first read registers the goal cell and
    # issues a move; the second live cell must not replace it.
    _patch_cursor(monkeypatch, (10.0, 10.0), [(900, 500), (500, 200)])
    nav._y_jump_step(mem, _Frame())
    assert mem['y_jump']['goal_cell'] == [900, 500]
    nav._y_jump_step(mem, _Frame())
    assert mem['y_jump']['goal_cell'] == [900, 500]


def test_a_castle_goal_is_unaffected(monkeypatch):
    mem = _mem()
    mem['y_jump']['goal'] = 'オシロガ'
    _patch_cursor(monkeypatch, (10.0, 10.0), [(900, 500), (500, 200)])
    nav._y_jump_step(mem, _Frame())
    assert 'goal_cell' not in mem['y_jump']
